// ===========================================================================
// SWAPPABLE NODE. This is the ONLY place the Apify actor input is defined.
// Mirrors apify/website-content-crawler-input.json. To change the actor input,
// edit the object inside buildApifyInput() and nothing else in this workflow.
// startUrls is the only field built at runtime.
// ===========================================================================
function buildApifyInput(pageUrls) {
  return {
    startUrls: pageUrls.map(function (u) { return { url: u }; }),
    crawlerType: 'playwright:adaptive',
    maxCrawlDepth: 0,
    maxCrawlPages: 3,
    maxResults: 3,
    htmlTransformer: 'none',
    removeElementsCssSelector: 'nav, footer, script, style, noscript',
    saveMarkdown: true,
    saveHtmlAsFile: false,
    saveScreenshots: false,
    summarize: false,
    proxyConfiguration: { useApifyProxy: true }
  };
}

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const c = items[i].json || {};
  const business = c.businesses || {};

  let pageUrls = Array.isArray(c.page_urls) ? c.page_urls : [];
  pageUrls = pageUrls
    .map(function (u) { return String(u === null || u === undefined ? '' : u).trim(); })
    .filter(function (u) { return u.length > 0; })
    .slice(0, 3);
  // competitors.page_urls has a 1..3 cardinality CHECK, so it should never be
  // empty, but fall back to the main url rather than crawling nothing.
  if (pageUrls.length === 0 && c.url) pageUrls = [String(c.url)];

  out.push({
    json: {
      competitor_id: c.id,
      business_id: c.business_id,
      competitor_name: c.name || '',
      competitor_url: c.url || '',
      page_urls: pageUrls,
      business_name: business.name || '',
      business_category: business.category || '',
      business_city: business.city || '',
      business_offerings: business.offerings || '',
      apify_input: buildApifyInput(pageUrls)
    },
    pairedItem: { item: i }
  });
}
return out;

// Resolve the matching item from an upstream node. itemMatching() follows n8n's
// paired-item chain, which is correct even when a branch filtered items out; the
// index fallback keeps the demo alive if the chain is ever broken.
function ctx(nodeName, i) {
  const n = $(nodeName);
  try {
    const m = n.itemMatching(i);
    if (m && m.json) return m.json;
  } catch (e) {}
  const all = n.all();
  return ((all[i] || all[0]) || { json: {} }).json;
}

// Deterministic hash implemented inline on purpose: the Code node sandbox can
// block require('crypto'), so this workflow depends on no modules at all.
// Two independent 32-bit mixers concatenated into 16 hex chars.
function contentHash(str) {
  const s = String(str);
  let h1 = 0x811c9dc5;
  let h2 = 0x1b873593;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = (h1 ^ c) >>> 0;
    h1 = Math.imul(h1, 0x01000193) >>> 0;
    h2 = (h2 + c) >>> 0;
    h2 = Math.imul(h2, 0x85ebca6b) >>> 0;
    h2 = (h2 ^ (h2 >>> 13)) >>> 0;
  }
  const a = ('00000000' + (h1 >>> 0).toString(16)).slice(-8);
  const b = ('00000000' + (h2 >>> 0).toString(16)).slice(-8);
  return a + b;
}

function extractPrices(text) {
  const found = String(text).match(/(?:US\$|USD\s?|\$)\s?\d{1,4}(?:,\d{3})*(?:\.\d{1,2})?/g) || [];
  const seen = [];
  for (let i = 0; i < found.length; i++) {
    const p = found[i].replace(/\s+/g, '');
    if (seen.indexOf(p) === -1) seen.push(p);
    if (seen.length >= 80) break;
  }
  return seen;
}

function extractItems(text) {
  const lines = String(text).split('\n');
  const found = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].replace(/^[\s>*#|-]+/, '').trim();
    if (line.length < 3 || line.length > 200) continue;
    if (!/\$\s?\d/.test(line)) continue;
    if (found.indexOf(line) === -1) found.push(line);
    if (found.length >= 60) break;
  }
  return found;
}

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const c = ctx('Build Apify Actor Input', i);
  const raw = items[i].json || {};

  // The node runs with "Include Response Headers and Status" on, so the actor's
  // dataset array arrives under .body instead of being split across items.
  let dataset = raw.body !== undefined ? raw.body : raw;
  if (!Array.isArray(dataset)) {
    if (dataset && Array.isArray(dataset.items)) dataset = dataset.items;
    else if (dataset && typeof dataset === 'object') dataset = [dataset];
    else dataset = [];
  }

  let pages = dataset
    .map(function (p) {
      p = p || {};
      const md = p.markdown || p.text || p.content || '';
      return {
        url: String(p.url || p.loadedUrl || p.requestUrl || ''),
        markdown: String(md).replace(/\r\n/g, '\n').replace(/[ \t]+\n/g, '\n').trim()
      };
    })
    .filter(function (p) { return p.url !== '' || p.markdown !== ''; });

  // Sort by URL so the hash never depends on the order Apify happened to finish in.
  pages.sort(function (a, b) { return a.url < b.url ? -1 : (a.url > b.url ? 1 : 0); });
  pages = pages.map(function (p) {
    return { url: p.url, markdown: p.markdown, hash: contentHash(p.url + '\n' + p.markdown) };
  });

  const combined = pages
    .map(function (p) { return '### ' + p.url + '\n\n' + p.markdown; })
    .join('\n\n---\n\n');

  out.push({
    json: {
      competitor_id: c.competitor_id,
      business_id: c.business_id,
      competitor_name: c.competitor_name,
      competitor_url: c.competitor_url,
      business_name: c.business_name,
      business_category: c.business_category,
      business_city: c.business_city,
      business_offerings: c.business_offerings,
      page_count: pages.length,
      pages: pages,
      current_content: combined,
      content_hash: contentHash(combined),
      structured: {
        prices: extractPrices(combined),
        items: extractItems(combined),
        hours: null
      }
    },
    pairedItem: { item: i }
  });
}
return out;

// Resolve the matching item from an upstream node. itemMatching() follows n8n's
// paired-item chain, which is correct even when a branch filtered items out; the
// index fallback keeps the demo alive if the chain is ever broken.
function ctx(nodeName, i) {
  const n = $(nodeName);
  try {
    const m = n.itemMatching(i);
    if (m && m.json) return m.json;
  } catch (e) {}
  const all = n.all();
  return ((all[i] || all[0]) || { json: {} }).json;
}

function pagesToText(pages) {
  if (!Array.isArray(pages)) return '';
  return pages
    .map(function (p) {
      p = p || {};
      return '### ' + String(p.url || '') + '\n\n' + String(p.markdown || '');
    })
    .join('\n\n---\n\n');
}

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const body = (items[i].json || {}).body;
  const rows = Array.isArray(body) ? body : [];
  const prev = rows.length > 0 ? rows[0] : null;
  const n = ctx('Normalize Crawl Output', i);

  let branch;
  if (!prev) branch = 'baseline';
  else if (String(prev.content_hash) === String(n.content_hash)) branch = 'unchanged';
  else branch = 'change';

  out.push({
    json: Object.assign({}, n, {
      branch: branch,
      previous_snapshot_id: prev ? prev.id : null,
      previous_captured_at: prev ? prev.captured_at : null,
      previous_content: prev ? pagesToText(prev.pages) : ''
    }),
    pairedItem: { item: i }
  });
}
return out;

// Resolve the matching item from an upstream node. itemMatching() follows n8n's
// paired-item chain, which is correct even when a branch filtered items out;
// the index fallback keeps the demo alive if the chain is ever broken.
function ctx(nodeName, i) {
  const n = $(nodeName);
  try {
    const m = n.itemMatching(i);
    if (m && m.json) return m.json;
  } catch (e) {}

  const all = n.all();
  return ((all[i] || all[0]) || { json: {} }).json;
}

// ===========================================================================
// Guardrail between model output and Postgres.
//
// Important design:
// - The model proposes an insight.
// - Code verifies/grounds the evidence against the actual crawl.
// - Stored evidence always comes from the crawl, never from model paraphrasing.
// ===========================================================================

const ALLOWED_SIGNAL_TYPE = ['baseline', 'change'];
const ALLOWED_CATEGORY = [
  'pricing',
  'promotion',
  'menu_product',
  'hours',
  'reputation',
  'positioning'
];
const ALLOWED_IMPACT = ['high', 'medium', 'low'];

const REQUIRED_TEXT = [
  'title',
  'finding',
  'why_it_matters',
  'recommended_action',
  'evidence'
];

const IMPACT_ORDER = {
  high: 0,
  medium: 1,
  low: 2
};

const MAX_SIGNALS = 3;

// Words that do not help us establish whether two passages discuss
// the same commercial fact.
const STOP_WORDS = new Set([
  'a', 'an', 'the', 'and', 'or', 'but',
  'is', 'are', 'was', 'were', 'be', 'been', 'being',
  'to', 'of', 'in', 'on', 'at', 'for', 'from', 'with',
  'by', 'as', 'into', 'about', 'over', 'under',
  'this', 'that', 'these', 'those',
  'their', 'they', 'them', 'its', 'it',
  'has', 'have', 'had',
  'now', 'currently',
  'location'
]);

function parseLoose(text) {
  if (text === null || text === undefined) return null;

  let t = String(text).trim();
  t = t
    .replace(/^```[a-zA-Z]*\s*/, '')
    .replace(/```\s*$/, '')
    .trim();

  try {
    return JSON.parse(t);
  } catch (e) {}

  const candidates = [t.indexOf('{'), t.indexOf('[')]
    .filter(function (x) {
      return x >= 0;
    });

  if (candidates.length === 0) return null;

  const start = Math.min.apply(null, candidates);
  const end = t.lastIndexOf(t.charAt(start) === '{' ? '}' : ']');

  if (end <= start) return null;

  try {
    return JSON.parse(t.slice(start, end + 1));
  } catch (e) {}

  return null;
}

function toArray(parsed) {
  if (Array.isArray(parsed)) return parsed;

  if (parsed && typeof parsed === 'object') {
    const keys = ['signals', 'data', 'results', 'items', 'output'];

    for (let i = 0; i < keys.length; i++) {
      if (Array.isArray(parsed[keys[i]])) {
        return parsed[keys[i]];
      }
    }

    if (parsed.title || parsed.finding) {
      return [parsed];
    }
  }

  return [];
}

function clean(v) {
  if (v === null || v === undefined) return '';
  return (typeof v === 'string' ? v : String(v)).trim();
}

function enumOf(v) {
  return clean(v)
    .toLowerCase()
    .replace(/[\s-]+/g, '_');
}

// Normalize text only for matching.
// We NEVER store this normalized version as evidence.
function canonical(v) {
  return clean(v)
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[’‘]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/[–—−]/g, '-')
    .replace(/\b(monday|mon)\b/g, 'mon')
    .replace(/\b(tuesday|tues|tue)\b/g, 'tue')
    .replace(/\b(wednesday|weds|wed)\b/g, 'wed')
    .replace(/\b(thursday|thurs|thur|thu)\b/g, 'thu')
    .replace(/\b(friday|fri)\b/g, 'fri')
    .replace(/\b(saturday|sat)\b/g, 'sat')
    .replace(/\b(sunday|sun)\b/g, 'sun')
    .replace(/\s+/g, ' ')
    .trim();
}

function meaningfulTokens(v) {
  const normalized = canonical(v)
    .replace(/[^a-z0-9$€£%:.+-]+/g, ' ');

  const parts = normalized
    .split(/\s+/)
    .filter(Boolean);

  const seen = {};
  const out = [];

  for (let i = 0; i < parts.length; i++) {
    const token = parts[i];

    if (STOP_WORDS.has(token)) continue;
    if (token.length < 2) continue;
    if (seen[token]) continue;

    seen[token] = true;
    out.push(token);
  }

  return out;
}

// Extract hard numeric anchors.
//
// A fabricated "$4.50", "30%", "9:00pm", etc. must exist in the actual
// source excerpt or that candidate cannot ground the signal.
function numericAnchors(v) {
  const text = canonical(v);

  const re =
  /(?:[$€£]\s*)?\d+(?:[.,]\d+)?(?::\d{2})?\s*(?:am|pm|%|k|m)?(?![a-z])/gi;

  const found = [];
  let match;

  while ((match = re.exec(text)) !== null) {
    let anchor = match[0]
      .toLowerCase()
      .replace(/[$€£,\s]/g, '');

    // Treat 9pm and 9:00pm as the same factual value.
    const time = anchor.match(
      /^(\d{1,2})(?::(\d{2}))?(am|pm)$/
    );

    if (time) {
      anchor =
        String(parseInt(time[1], 10)) +
        ':' +
        (time[2] || '00') +
        time[3];
    }

    if (anchor && found.indexOf(anchor) === -1) {
      found.push(anchor);
    }
  }

  return found;
}

function containsAllNumericAnchors(candidate, proposed) {
  const required = numericAnchors(proposed);

  if (required.length === 0) {
    return true;
  }

  const candidateNumbers = numericAnchors(candidate);

  for (let i = 0; i < required.length; i++) {
    if (candidateNumbers.indexOf(required[i]) === -1) {
      return false;
    }
  }

  return true;
}

// Build short, contiguous excerpts from the original markdown.
//
// Because each candidate is sliced directly from the original crawl,
// anything returned here is guaranteed to be real source text.
function buildSourceCandidates(markdown) {
  const source = String(markdown || '');
  const lines = [];

  const re = /[^\n]+/g;
  let match;

  while ((match = re.exec(source)) !== null) {
    if (!clean(match[0])) continue;

    lines.push({
      start: match.index,
      end: match.index + match[0].length
    });
  }

  const candidates = [];
  const MAX_LINES = 6;
  const MAX_LENGTH = 700;

  for (let i = 0; i < lines.length; i++) {
    for (
      let width = 1;
      width <= MAX_LINES && i + width - 1 < lines.length;
      width++
    ) {
      const first = lines[i];
      const last = lines[i + width - 1];

      const text = source
        .slice(first.start, last.end)
        .trim();

      if (!text) continue;
      if (text.length > MAX_LENGTH) break;

      candidates.push(text);
    }
  }

  return candidates;
}

function tokenCoverage(queryTokens, candidate) {
  if (queryTokens.length === 0) return 0;

  const candidateTokens = meaningfulTokens(candidate);
  const candidateSet = {};

  for (let i = 0; i < candidateTokens.length; i++) {
    candidateSet[candidateTokens[i]] = true;
  }

  let overlap = 0;

  for (let i = 0; i < queryTokens.length; i++) {
    if (candidateSet[queryTokens[i]]) {
      overlap++;
    }
  }

  return {
    overlap: overlap,
    coverage: overlap / queryTokens.length
  };
}

const GENERIC_CLAIM_WORDS = new Set([
  'competitor',
  'offer',
  'offers',
  'offering',
  'has',
  'have',
  'include',
  'includes',
  'feature',
  'features',
  'menu',
  'business',
  'restaurant',
  'currently',
  'now',
  'location',
  'locations',
  'open',
  'opens',
  'hours',
  'until',
  'weekend',
  'weekends'
]);

function claimTokens(value, competitorName) {
  const brandTokens = new Set(
    meaningfulTokens(competitorName)
  );

  return meaningfulTokens(value).filter(function (token) {
    if (brandTokens.has(token)) return false;
    if (GENERIC_CLAIM_WORDS.has(token)) return false;
    if (numericAnchors(token).length > 0) return false;

    return true;
  });
}

function claimSupportedByEvidence(
  claim,
  evidence,
  competitorName
) {
  // Numbers claimed by the model must exist in the evidence.
  const claimNumbers = numericAnchors(claim);
  const evidenceNumbers = numericAnchors(evidence);

  for (let i = 0; i < claimNumbers.length; i++) {
    if (evidenceNumbers.indexOf(claimNumbers[i]) === -1) {
      return false;
    }
  }

  const tokens = claimTokens(claim, competitorName);

  if (tokens.length === 0) {
    return true;
  }

  const evidenceTokens = new Set(
    meaningfulTokens(evidence)
  );

  let overlap = 0;

  for (let i = 0; i < tokens.length; i++) {
    if (evidenceTokens.has(tokens[i])) {
      overlap++;
    }
  }

  // For short claims, require every meaningful factual term.
  if (tokens.length <= 3) {
    return overlap === tokens.length;
  }

  // For longer paraphrases, require strong support.
  return overlap >= 3 &&
    overlap / tokens.length >= 0.75;
}

// Returns:
// {
//   url: "...",
//   evidence: "EXACT TEXT FROM CRAWL",
//   mode: "exact" | "grounded",
//   score: ...
// }
//
// Returns null if the model's proposed evidence cannot be sufficiently
// grounded in any crawled page.
function groundEvidence(pages, proposedEvidence) {
  const quote = clean(proposedEvidence);
  const list = Array.isArray(pages) ? pages : [];

  if (!quote || list.length === 0) {
    return null;
  }

  // ------------------------------------------------------------
  // 1. Best case: GPT actually copied a true verbatim substring.
  // ------------------------------------------------------------
  for (let i = 0; i < list.length; i++) {
    const page = list[i] || {};
    const markdown = String(page.markdown || '');

    if (markdown.includes(quote)) {
      return {
        url: String(page.url || ''),
        evidence: quote,
        mode: 'exact',
        score: 1
      };
    }
  }

  // ------------------------------------------------------------
  // 2. GPT paraphrased it. Find the closest real source excerpt.
  // ------------------------------------------------------------
  const queryTokens = meaningfulTokens(quote);
  const proposedNumbers = numericAnchors(quote);

  if (queryTokens.length === 0) {
    return null;
  }

  let best = null;

  for (let p = 0; p < list.length; p++) {
    const page = list[p] || {};
    const markdown = String(page.markdown || '');

    if (!markdown) continue;

    const candidates = buildSourceCandidates(markdown);

    for (let c = 0; c < candidates.length; c++) {
      const candidate = candidates[c];

      // Numbers are hard anchors. A fake price/time cannot be fuzzily rescued.
      if (!containsAllNumericAnchors(candidate, quote)) {
        continue;
      }

      const matchStats = tokenCoverage(queryTokens, candidate);
      const overlap = matchStats.overlap;
      const coverage = matchStats.coverage;

      // If GPT supplied a number, that number must exist AND we need a
      // reasonable semantic overlap.
      //
      // Without a numeric anchor, demand much stronger lexical support.
      const minimumCoverage =
        proposedNumbers.length > 0 ? 0.30 : 0.60;

      if (overlap < 2) continue;
      if (coverage < minimumCoverage) continue;

      // Prefer higher token coverage and shorter, more precise excerpts.
      const score =
        coverage +
        Math.min(overlap, 8) * 0.02 -
        Math.min(candidate.length, 700) * 0.00005;

      if (!best || score > best.score) {
        best = {
          url: String(page.url || ''),
          evidence: candidate,
          mode: 'grounded',
          score: score
        };
      }
    }
  }

  return best;
}

// Repair only safe, obvious advisory prefixes.
//
// We intentionally do NOT turn every vague recommendation into an action.
// Example:
//   "Evaluate your pricing..." remains vague and will still be rejected.
//
// But:
//   "Consider extending Friday hours to 7pm..."
// becomes:
//   "Test extending Friday hours to 7pm..."
function normalizeRecommendedAction(value) {
  let action = clean(value);

  action = action.replace(
    /^consider\s+(?:whether\s+to\s+)?/i,
    'Test '
  );

  action = action.replace(
    /^evaluate\s+the\s+feasibility\s+of\s+/i,
    'Test '
  );

  action = action.replace(
    /^think\s+about\s+/i,
    'Test '
  );

  return action.trim();
}

const VAGUE_ACTION_PATTERN =
  /\b(consider|evaluate|review|reassess|think about)\b/i

const UNSUPPORTED_OWNER_ABSENCE_PATTERN =
  /\b(?:does not|doesn't|do not|don't)\s+(?:currently\s+)?(?:offer|have|provide|sell|include)\b|\blacks?\b/i;

const COPY_COMPETITOR_ACTION_PATTERN =
  /\bto\s+match\b|\bmatch(?:ing)?\s+(?:their|the competitor(?:'s)?)\b/i;

const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const d = ctx('Classify Scan Branch', i);

  const expectedType =
    d.branch === 'baseline' ? 'baseline' : 'change';

  const resp = items[i].json || {};

  let content = '';

  try {
    content = resp.choices[0].message.content;
  } catch (e) {
    content = '';
  }

  const raw = toArray(parseLoose(content));
  const kept = [];
  const dropped = [];

  for (let k = 0; k < raw.length; k++) {
    const s = raw[k] || {};

    const declaredType = enumOf(s.signal_type);
    const category = enumOf(s.category);
    const impact = enumOf(s.impact);

    // ------------------------------------------------------------
    // Enum validation
    // ------------------------------------------------------------

    if (
      declaredType !== '' &&
      ALLOWED_SIGNAL_TYPE.indexOf(declaredType) === -1
    ) {
      dropped.push(
        'signal_type not in enum: ' + declaredType
      );
      continue;
    }

    if (ALLOWED_CATEGORY.indexOf(category) === -1) {
      dropped.push(
        'category not in enum: ' + category
      );
      continue;
    }

    if (ALLOWED_IMPACT.indexOf(impact) === -1) {
      dropped.push(
        'impact not in enum: ' + impact
      );
      continue;
    }

    // ------------------------------------------------------------
    // Required fields
    // ------------------------------------------------------------

    const text = {};
    let missing = '';

    for (let f = 0; f < REQUIRED_TEXT.length; f++) {
      const field = REQUIRED_TEXT[f];
      const val = clean(s[field]);

      if (val === '') {
        missing = field;
        break;
      }

      text[field] = val;
    }

    if (missing !== '') {
      dropped.push(
        'empty required field: ' + missing
      );
      continue;
    }

    // ------------------------------------------------------------
    // Evidence grounding FIRST.
    //
    // This is intentionally checked before action phrasing so the
    // dropped reason tells us about hallucinations before style issues.
    // ------------------------------------------------------------

    const grounded = groundEvidence(
      d.pages,
      text.evidence
    );

    if (!grounded || !grounded.url) {
      dropped.push(
        'evidence could not be grounded in crawled pages: ' +
        text.evidence
      );
      continue;
    }

    // On a baseline scan, any numbers claimed in title/finding should also
    // appear in the real grounded source excerpt.
    //
    // We skip this strict rule for change scans because a finding can
    // legitimately mention both the previous and current values.
    if (expectedType === 'baseline') {
      const claimNumbers = numericAnchors(
        text.title + ' ' + text.finding
      );

      const groundedNumbers = numericAnchors(
        grounded.evidence
      );

      let unsupportedNumber = '';

      for (let n = 0; n < claimNumbers.length; n++) {
        if (
          groundedNumbers.indexOf(claimNumbers[n]) === -1
        ) {
          unsupportedNumber = claimNumbers[n];
          break;
        }
      }

      if (unsupportedNumber) {
        dropped.push(
          'baseline claim contains number not present in grounded evidence: ' +
          unsupportedNumber
        );
        continue;
      }
    }

    const claimText = text.finding;

    if (
      !claimSupportedByEvidence(
        claimText,
        grounded.evidence,
        d.competitor_name
      )
    ) {
      dropped.push(
        'grounded evidence does not sufficiently support title/finding: ' +
        text.title
      );
      continue;
    }

    if (
  UNSUPPORTED_OWNER_ABSENCE_PATTERN.test(
        text.why_it_matters
      )
    ) {
      dropped.push(
        'why_it_matters makes an unsupported claim about what the owner lacks: ' +
        text.why_it_matters
      );
      continue;
    }

    // ------------------------------------------------------------
    // Recommended action
    // ------------------------------------------------------------

    const recommendedAction =
      normalizeRecommendedAction(
        text.recommended_action
      );

    if (
      VAGUE_ACTION_PATTERN.test(recommendedAction)
    ) {
      dropped.push(
        'recommended_action remains vague after normalization: ' +
        recommendedAction
      );
      continue;
    }

    if (
      COPY_COMPETITOR_ACTION_PATTERN.test(
        recommendedAction
      )
    ) {
      dropped.push(
        'recommended_action copies the competitor without sufficient justification: ' +
        recommendedAction
      );
      continue;
    }

    // If the actual finding contains a measurable number, the action
    // should also contain a concrete number.
    const findingNumbers = numericAnchors(
      text.title + ' ' + text.finding
    );

    if (
      findingNumbers.length > 0 &&
      numericAnchors(recommendedAction).length === 0
    ) {
      dropped.push(
        'measurable signal has no concrete number in recommended_action: ' +
        recommendedAction
      );
      continue;
    }

    // ------------------------------------------------------------
    // Keep validated signal.
    //
    // IMPORTANT:
    // evidence is grounded.evidence, NOT the model's proposed evidence.
    // ------------------------------------------------------------

    kept.push({
      signal_type: expectedType,
      category: category,
      impact: impact,
      title: text.title.slice(0, 300),
      finding: text.finding,
      why_it_matters: text.why_it_matters,
      recommended_action: recommendedAction,
      evidence: grounded.evidence.slice(0, 2000),
      source_url: grounded.url
    });
  }

  kept.sort(function (a, b) {
    return (
      IMPACT_ORDER[a.impact] -
      IMPACT_ORDER[b.impact]
    );
  });

  const signals = kept.slice(0, MAX_SIGNALS);

  out.push({
    json: {
      competitor_id: d.competitor_id,
      business_id: d.business_id,
      branch: d.branch,
      content_hash: d.content_hash,
      pages: d.pages,
      structured: d.structured,
      signal_count: signals.length,
      signals: signals,
      dropped_count: dropped.length,
      dropped_reasons: dropped.slice(0, 10)
    },
    pairedItem: { item: i }
  });
}

return out;

// Resolve the matching item from an upstream node. itemMatching() follows n8n's
// paired-item chain, which is correct even when a branch filtered items out; the
// index fallback keeps the demo alive if the chain is ever broken.
function ctx(nodeName, i) {
  const n = $(nodeName);
  try {
    const m = n.itemMatching(i);
    if (m && m.json) return m.json;
  } catch (e) {}
  const all = n.all();
  return ((all[i] || all[0]) || { json: {} }).json;
}

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const snapshot = items[i].json || {};
  const v = ctx('Validate Signals', i);
  const snapshotId = snapshot.id || null;

  const rows = (Array.isArray(v.signals) ? v.signals : []).map(function (s) {
    return {
      business_id: v.business_id,
      competitor_id: v.competitor_id,
      snapshot_id: snapshotId,
      signal_type: s.signal_type,
      category: s.category,
      impact: s.impact,
      title: s.title,
      finding: s.finding,
      why_it_matters: s.why_it_matters,
      recommended_action: s.recommended_action,
      evidence: s.evidence,
      source_url: s.source_url || null
    };
  });

  out.push({
    json: {
      competitor_id: v.competitor_id,
      business_id: v.business_id,
      snapshot_id: snapshotId,
      signal_count: rows.length,
      signal_rows: rows
    },
    pairedItem: { item: i }
  });
}
return out;

// Every terminating path converges here: unchanged early-exit, signals inserted,
// and no-signals. Collapses to one item per competitor so the final PATCH runs once.
const seen = {};
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const id = j.competitor_id || j.id;
  if (!id || seen[id]) continue;
  seen[id] = true;
  out.push({
    json: {
      competitor_id: id,
      branch: j.branch || null,
      signal_count: j.signal_count === undefined ? null : j.signal_count
    },
    pairedItem: { item: i }
  });
}
return out;
